 if (select count(*) from vocab_private.bank_authoring_items where user_id='06c78577-b96e-4919-b979-58683ff5946e' and batch_key='vocab-bank-offline-20261014-v1' and word in ('증여','예측') and status='authored_draft')<>20 then raise exception 'Missing compatibility bank slots';end if;
